/******************************************************************************/
/*                                                                            */
/*                                    FLASH                                   */
/*                                                                            */
/******************************************************************************/
#define FLASH_LATENCY_DEFAULT      (FLASH_ACR_LATENCY_1 | FLASH_ACR_LATENCY_0) /* default flash latency 3WS */
#define FLASH_OTP_SIZE             (0x400U)                                    /* 1 Kbyte OTP (one-time programmable) */

#define FLASH_BANK_SIZE            (FLASH_SIZE >> 1U)                          /* 256 Kbytes per bank */

#define FLASH_PAGE_SIZE            0x2000U                                     /* 8 Kbytes pages    */
#define FLASH_PAGE_NB              (FLASH_BANK_SIZE/FLASH_PAGE_SIZE)           /* 32 user flash pages per bank */
#define FLASH_BANK_NB              (2U)
/******************  Bit definition for FLASH_ACCR register  ******************/
#define FLASH_ACCR_LATENCY_Pos               (0U)
#define FLASH_ACCR_LATENCY_Msk               (0xFUL << FLASH_ACCR_LATENCY_Pos)                   /*!< 0x0000000F */
#define FLASH_ACCR_LATENCY                   FLASH_ACCR_LATENCY_Msk                              /*!< LATENCY[3:0] bits (Read latency) */
#define FLASH_ACCR_LATENCY_0                 (0x1UL << FLASH_ACCR_LATENCY_Pos)                   /*!< 0x00000001 */
#define FLASH_ACCR_LATENCY_1                 (0x2UL << FLASH_ACCR_LATENCY_Pos)                   /*!< 0x00000002 */
#define FLASH_ACCR_LATENCY_2                 (0x4UL << FLASH_ACCR_LATENCY_Pos)                   /*!< 0x00000004 */
#define FLASH_ACCR_LATENCY_3                 (0x8UL << FLASH_ACCR_LATENCY_Pos)                   /*!< 0x00000008 */
#define FLASH_ACCR_WRHIGHFREQ_Pos            (4U)
