/* ************************************************* ADC Instances ************************************************** */
#define IS_ADC_ALL_INSTANCE(INSTANCE) (((INSTANCE) == ADC1) || ((INSTANCE) == ADC2) \
                                       || ((INSTANCE) == ADC3) || ((INSTANCE) == ADC4))

#define IS_ADC_MULTIMODE_MASTER_INSTANCE(INSTANCE) (((INSTANCE) == ADC1) || ((INSTANCE) == ADC3))

#define IS_ADC_COMMON_INSTANCE(INSTANCE) (((INSTANCE) == ADC12_COMMON) \
                                          || ((INSTANCE) == ADC34_COMMON))

/* Select the ADC common instance to which belongs the selected ADC instance */
#define ADC_COMMON_INSTANCE(adc_instance) \
  ((((adc_instance) == ADC1) || ((adc_instance) == ADC2)) ? (ADC12_COMMON) : (ADC34_COMMON))

/* Select the ADC multimode instance master corresponding to the selected ADC instance */
#define ADC_MULTI_INSTANCE_MASTER(adc_instance) (((adc_instance) == ADC2) ? (ADC1) \
                                                 : (((adc_instance) == ADC4) ? (ADC3) : (adc_instance)))

/******************************* ADF Instances ********************************/
#define IS_ADF_ALL_INSTANCE(INSTANCE)   ((INSTANCE) == ADF1)

#define ADF1_BLOCKS_NUMBER 1U
#define ADF1_BLOCK_SIZE    0x80UL

